// These are the heights the note chooser itself writes for this layout
// (`NOTE_CHOICES`, id `bands`), and the engine now reserves the page foot from
// exactly them: `auto_notes_region_cm` reads `גבהים` and adds up what is asked
// for. It used to reserve a flat 3 cm for any page apparatus and never read the
// line at all — so a template that invented its own heights could put a band off
// the bottom of the paper, and 3.5 + 2.5 put the second one 51pt below the edge
// of A4 with the page number under it. Any two numbers are safe here now; these
// are the product's own because a starting point should look like what the
// chooser produces.
#הגדרות_מדפים(גבהים: (1.5cm, 1cm), גודל: (0.85em, 0.8em))

#שער[מסכת ברכות — דף ל״ה ע״א]
#תת_שער[עם פירוש ובאורים בשולי העמוד]

#קו_מפריד

#סימן[א׳][כיצד מברכין]

מַתְנִיתִין: כֵּיצַד מְבָרְכִין עַל הַפֵּירוֹת? עַל פֵּירוֹת הָאִילָן הוּא אוֹמֵר בּוֹרֵא פְּרִי הָעֵץ#מדף_א[
פירוש: כל פרי הגדל באילן, והוא שיהיה הגזע קיים משנה לשנה. וכן פסק #ציון_מקור("שולחן ערוך", מקום: "אורח חיים סימן ר״ג").
]#מדף_ב[
ועיין במה שדנו האחרונים בפירות האדמה הגדלים על שיח, ומה נשתנה בהם.
], חוּץ מִן הַיַּיִן, שֶׁעַל הַיַּיִן הוּא אוֹמֵר בּוֹרֵא פְּרִי הַגָּפֶן.

וְעַל פֵּירוֹת הָאָרֶץ הוּא אוֹמֵר בּוֹרֵא פְּרִי הָאֲדָמָה#מדף_א[
כגון ירקות וקטניות, וכן הפת קודם שנעשית פת. #ציון_מקור("ברכות", מקום: "ל״ה ע״ב").
], חוּץ מִן הַפַּת, שֶׁעַל הַפַּת הוּא אוֹמֵר הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ.

#סימן[ב׳][גמרא]

גְּמָרָא: מְנָא הָנֵי מִילֵּי? דְּתָנוּ רַבָּנַן

#פסוק[ויקרא י״ט, כ״ד][קֹדֶשׁ הִלּוּלִים לַה׳],

מְלַמֵּד שֶׁטְּעוּנִים בְּרָכָה לִפְנֵיהֶם וּלְאַחֲרֵיהֶם#מדף_א[
דרשה זו היא המקור לברכת הנהנין כולה, ועיין #ציון_מקור("רמב״ם", מקום: "הלכות ברכות פרק א׳").
]#מדף_ב[
ויש שלמדו מסברא, ועיין במה שהאריכו בזה הראשונים.
].

#קו_מפריד

#מפתח_מקורות()

שורה של פרוזה ובה מלים#רשימת_הגדרות(
  הגדרה[][],
)אחרות להמשך.

A line of prose with some wor#deflist(
  defitem[][],
)ds to continue.

#טבלה(עמודות: (1fr, 1fr),
  תא[אחד #הגדרות_כותרות(גודל: (2em, 1.4em), צבע: (rgb("#b91c1c"), luma(40)), מספור: "1.1", קו: (true, false))כאן], תא[שתים],
)

#טבלה(עמודות: (1fr, 1fr),
  תא[אחד #הגדרות_טבלאות(פסים: true, צבע_כותרת: rgb("#dbeafe"), מרווח: 10pt)כאן], תא[שתים],
)

#mktable(columns: (1fr, 1fr),
  cell[one #headings_config(size: (2em, 1.4em), colour: (rgb("#b91c1c"), luma(40)), numbering: "1.1", rule: (true, false))here], cell[two],
)

#mktable(columns: (1fr, 1fr),
  cell[one #tables_config(striped: true, header_fill: rgb("#dbeafe"), inset: 10pt)here], cell[two],
)

#טבלה(עמודות: (1fr, 1fr),
  תא[אחד],הגדרות_כותרות(גודל: (2em, 1.4em), צבע: (rgb("#b91c1c"), luma(40)), מספור: "1.1", קו: (true, false)), תא[שתים],
)

#טבלה(עמודות: (1fr, 1fr),
  תא[אחד],הגדרות_טבלאות(פסים: true, צבע_כותרת: rgb("#dbeafe"), מרווח: 10pt), תא[שתים],
)

#mktable(columns: (1fr, 1fr),
  cell[one],headings_config(size: (2em, 1.4em), colour: (rgb("#b91c1c"), luma(40)), numbering: "1.1", rule: (true, false)), cell[two],
)

#mktable(columns: (1fr, 1fr),
  cell[one],tables_config(striped: true, header_fill: rgb("#dbeafe"), inset: 10pt), cell[two],
)

#רשימה(
  פריט[ראשון #הערה[בהערה #הגדרות_כותרות(גודל: (2em, 1.4em), צבע: (rgb("#b91c1c"), luma(40)), מספור: "1.1", קו: (true, false))כאן] סוף],
)

#רשימה(
  פריט[ראשון #הערה[בהערה #הגדרות_טבלאות(פסים: true, צבע_כותרת: rgb("#dbeafe"), מרווח: 10pt)כאן] סוף],
)

#bullets(
  item[first #fnote[in a note #headings_config(size: (2em, 1.4em), colour: (rgb("#b91c1c"), luma(40)), numbering: "1.1", rule: (true, false))here] end],
)

#bullets(
  item[first #fnote[in a note #bullets(
  item[],
  item[],
)here] end],
)

#bullets(
  item[first #fnote[in a note #numbered(
  item[],
  item[],
)here] end],
)

#bullets(
  item[first #fnote[in a note #henum(
  item[],
  item[],
)here] end],
)

#bullets(
  item[first #fnote[in a note #lists_config(marker: ([◆], [–]), indent: 1.5em, tight: true)here] end],
)

#bullets(
  item[first #fnote[in a note #tables_config(striped: true, header_fill: rgb("#dbeafe"), inset: 10pt)here] end],
)

#bullets(
  item[first #fnote[in a note #region("", placement: "foot", height: 3cm)here] end],
)

#bullets(
  item[first #fnote[in a note #footnote_config(style: ("normal", "italic"), indent: (0em, 1em), numbering: ("א", "1", "i"))here] end],
)
